1	import 'package:cerne/core/network/failure.dart';
2	
3	/// Maps a backend error response body (`{code, message, retryable,
4	/// requestId}`) to its typed [Failure] subtype. An unrecognized `code` MUST
5	/// NOT throw — it is mapped to a defensive [ValidationFailure] instead
6	/// (contracts/failure-taxonomy.md; FR-003 "never an unhandled crash").
7	class ErrorMapper {
8	  const ErrorMapper._();
9	
10	  static Failure fromResponse(Map<String, dynamic> body) {
11	    final code = body['code'] as String?;
12	    final message = body['message'] as String? ?? 'Unknown error';
13	    final requestId = body['requestId'] as String? ?? '';
14	
15	    return switch (code) {
16	      'AUTH_EXPIRED' => AuthExpiredFailure(message: message, requestId: requestId),
