10	class AuthBloc extends Bloc<AuthEvent, AuthState> {
11	  AuthBloc({required this._loginUseCase, required this._signUpUseCase})
12	      : super(const AuthState()) {
13	    on<LoginSubmitted>(_onLoginSubmitted);
14	    on<SignUpSubmitted>(_onSignUpSubmitted);
15	    on<ToggleModeRequested>(_onToggleModeRequested);
16	  }
17	
18	  final LoginUseCase _loginUseCase;
19	  final SignUpUseCase _signUpUseCase;
20	
21	  Future<void> _onLoginSubmitted(
22	    LoginSubmitted event,
23	    Emitter<AuthState> emit,
24	  ) async {
25	    // Guards against a concurrent submit: a backgrounded-resume double-tap
26	    // never produces a second network call / duplicate session (Edge Cases).
27	    if (state.status == AuthStatus.loading) return;
28	
29	    emit(AuthState(status: AuthStatus.loading, formMode: state.formMode));
30	    final result = await _loginUseCase(email: event.email, password: event.password);
31	    _emitResult(result, emit);
